// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, address newDao, bool configured) public {
        // Configure the contract: if configured is true, call endConfiguration
        vm.assume(configured == false || configured == true);
        if (configured) {
            c.endConfiguration();
        }

        // Try to set the DAO with caller as msg.sender
        vm.prank(caller);

        // Execute setDAO
        bool success;
        bytes memory data = abi.encodeWithSignature("setDAO(address)", newDao);
        (success, ) = address(c).call(data);

        // The rule: setDAO should revert if the contract is configured AND msg.sender is not the DAO AND the DAO is not address(0)
        // After the call, check if the DAO was actually changed
        address currentDao = c.DAO();
        bool daoChanged = (currentDao == newDao);

        // If setDAO succeeded, we must have satisfied one of the conditions
        // If it reverted, no state change
        if (success) {
            // Either the DAO was previously address(0) or caller was the previous DAO or not configured
            assertTrue(
                (!configured) || (caller == address(this)) || (newDao == address(0)),
                "setDAO should have reverted"
            );
        } else {
            // If it reverted, the contract was configured and caller was not the previous DAO (which is address(this))
            assertTrue(
                configured && caller != address(this),
                "setDAO should not have reverted"
            );
        }
    }
}

